package com.communityfix;

import com.communityfix.common.Db;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.http.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"communityfix.wechat.order-template-id=","communityfix.ai.endpoint="})
@EnabledIfEnvironmentVariable(named="CF_INTEGRATION",matches="true")
class CommunityDeletionTest {
 @Test void cleanupRemovesEmptyHierarchyAndOnlyTargetGrants(){String root=login("admin");long id=create(root),other=create(root),pid=Db.id(db.required("SELECT id FROM sys_user WHERE username='property'"),"id");long b=db.insert("building",Db.fields("community_id",id,"building_no","1")),u=db.insert("unit",Db.fields("building_id",b,"unit_no","1"));db.insert("room",Db.fields("unit_id",u,"room_no","101","floor",1));db.execute("INSERT INTO admin_community(user_id,community_id) VALUES (?,?),(?,?)",pid,id,pid,other);int version=Db.integer(db.required("SELECT token_version FROM sys_user WHERE id=?",pid),"tokenVersion");var preview=ok(call(root,HttpMethod.GET,"/manage/communities/"+id+"/deletion-check",null));assertTrue(preview.path("canCleanup").asBoolean());assertEquals(1,preview.path("configurationCounts").path("rooms").asInt());ok(call(root,HttpMethod.DELETE,"/manage/communities/"+id+"?cleanupEmptyConfiguration=true&confirmationToken="+preview.path("configurationToken").asText(),null));assertEquals(0,db.count("SELECT COUNT(*) FROM community WHERE id=?",id));assertEquals(0,db.count("SELECT COUNT(*) FROM unit WHERE id=?",u));assertEquals(1,db.count("SELECT COUNT(*) FROM admin_community WHERE user_id=? AND community_id=?",pid,other));assertEquals(version+1,Db.integer(db.required("SELECT token_version FROM sys_user WHERE id=?",pid),"tokenVersion"));}
 @Test void cleanupRequiresFreshConfirmationAndPreservesBindings(){String root=login("admin");long id=create(root);String token=ok(call(root,HttpMethod.GET,"/manage/communities/"+id+"/deletion-check",null)).path("configurationToken").asText();long b=db.insert("building",Db.fields("community_id",id,"building_no","1")),u=db.insert("unit",Db.fields("building_id",b,"unit_no","1")),r=db.insert("room",Db.fields("unit_id",u,"room_no","101","floor",1));assertEquals(409,call(root,HttpMethod.DELETE,"/manage/communities/"+id+"?cleanupEmptyConfiguration=true&confirmationToken="+token,null).getStatusCode().value());long resident=Db.id(db.required("SELECT id FROM sys_user WHERE username='resident'"),"id");db.insert("resident_room_binding",Db.fields("user_id",resident,"room_id",r));var check=ok(call(root,HttpMethod.GET,"/manage/communities/"+id+"/deletion-check",null));assertFalse(check.path("canCleanup").asBoolean());assertEquals(409,call(root,HttpMethod.DELETE,"/manage/communities/"+id+"?cleanupEmptyConfiguration=true&confirmationToken="+check.path("configurationToken").asText(),null).getStatusCode().value());assertEquals(1,db.count("SELECT COUNT(*) FROM room WHERE id=?",r));}
 @Autowired TestRestTemplate rest;@Autowired Db db;@Value("${communityfix.bootstrap-password}")String password;
 ResponseEntity<JsonNode> call(String token,HttpMethod method,String path,Object body){var h=new HttpHeaders();h.setContentType(MediaType.APPLICATION_JSON);if(token!=null)h.setBearerAuth(token);return rest.exchange("/api"+path,method,new HttpEntity<>(body,h),JsonNode.class);}
 JsonNode ok(ResponseEntity<JsonNode> r){assertEquals(200,r.getStatusCode().value(),()->String.valueOf(r.getBody()));return r.getBody().path("data");}
 String login(String name){return ok(call(null,HttpMethod.POST,"/auth/login",Map.of("username",name,"password",password))).path("token").asText();}
 long create(String token){return ok(call(token,HttpMethod.POST,"/manage/communities",Map.of("name","同名删除验证小区","address","测试地址"))).path("id").asLong();}
 @Test void deletesOnlyChosenEmptyCommunityAndAudits(){String root=login("admin");long first=create(root),second=create(root);ok(call(root,HttpMethod.PATCH,"/manage/communities/"+first,Map.of("status","DISABLED")));assertTrue(ok(call(root,HttpMethod.GET,"/manage/communities/"+first+"/deletion-check",null)).path("canDelete").asBoolean());ok(call(root,HttpMethod.DELETE,"/manage/communities/"+first,null));assertEquals(0,db.count("SELECT COUNT(*) FROM community WHERE id=?",first));assertEquals(1,db.count("SELECT COUNT(*) FROM community WHERE id=?",second));assertEquals(1,db.count("SELECT COUNT(*) FROM sys_operation_log WHERE action='COMMUNITY_DELETE' AND target_id=?",first));assertEquals(404,call(root,HttpMethod.DELETE,"/manage/communities/"+first,null).getStatusCode().value());ok(call(root,HttpMethod.DELETE,"/manage/communities/"+second,null));}
 @Test void onlySuperAdminMayDeleteOrInspect(){String root=login("admin");long id=create(root);for(String name:List.of("property","resident","worker")){String token=login(name);assertEquals(403,call(token,HttpMethod.GET,"/manage/communities/"+id+"/deletion-check",null).getStatusCode().value());assertEquals(403,call(token,HttpMethod.DELETE,"/manage/communities/"+id,null).getStatusCode().value());}assertEquals(401,call(null,HttpMethod.DELETE,"/manage/communities/"+id,null).getStatusCode().value());assertEquals(1,db.count("SELECT COUNT(*) FROM community WHERE id=?",id));}
 @Test void referencesAddedAfterPreviewBlockDeletion(){String root=login("admin");long id=create(root);assertTrue(ok(call(root,HttpMethod.GET,"/manage/communities/"+id+"/deletion-check",null)).path("canDelete").asBoolean());long bid=db.insert("building",Db.fields("community_id",id,"building_no","1"));var r=call(root,HttpMethod.DELETE,"/manage/communities/"+id,null);assertEquals(409,r.getStatusCode().value());assertEquals("COMMUNITY_IN_USE",r.getBody().path("errorCode").asText());assertEquals(1,db.count("SELECT COUNT(*) FROM building WHERE id=?",bid));assertFalse(ok(call(root,HttpMethod.GET,"/manage/communities/"+id+"/deletion-check",null)).path("canDelete").asBoolean());}
 @Test void propertyGrantsAndSupportHistoryAreProtected(){String root=login("admin");long id=create(root),pid=Db.id(db.required("SELECT id FROM sys_user WHERE username='property'"),"id");db.execute("INSERT INTO admin_community(user_id,community_id) VALUES (?,?)",pid,id);assertEquals(409,call(root,HttpMethod.DELETE,"/manage/communities/"+id,null).getStatusCode().value());db.execute("DELETE FROM admin_community WHERE user_id=? AND community_id=?",pid,id);db.insert("support_knowledge",Db.fields("community_id",id,"title","知识","keywords","测试","question","问题","answer","答案","updated_by",pid));var check=ok(call(root,HttpMethod.GET,"/manage/communities/"+id+"/deletion-check",null));assertTrue(check.toString().contains("support_knowledge"));assertEquals(409,call(root,HttpMethod.DELETE,"/manage/communities/"+id,null).getStatusCode().value());assertEquals(0,db.count("SELECT COUNT(*) FROM sys_operation_log WHERE action='COMMUNITY_DELETE' AND target_id=?",id));}
}
